"""Write a final, read-only selected-source and real-index preservation receipt."""

import hashlib
import json
from pathlib import Path
import subprocess
import time


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def git(*args):
    return subprocess.check_output(['git', *args], cwd=ROOT, text=True).strip()


def main():
    output = HERE / 'selected-source-verification.json'
    assert not output.exists(), 'Preserve existing receipt; do not overwrite it'
    initial_file = HERE / 'initial/identity.json'
    map_file = HERE / 'initial/module-sources.json'
    initial = json.loads(initial_file.read_text())
    original = json.loads(map_file.read_text())
    actual = {p.relative_to(ROOT).as_posix(): sha(p)
              for p in sorted((ROOT / 'core/sail/lmdb/src').rglob('*')) if p.is_file()}
    missing = sorted(original.keys() - actual.keys())
    added = sorted(actual.keys() - original.keys())
    changed = sorted(k for k in original.keys() & actual.keys() if original[k] != actual[k])
    index_path = Path(git('rev-parse', '--git-path', 'index'))
    if not index_path.is_absolute():
        index_path = ROOT / index_path
    materializer = 'core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java'
    test = 'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializerTest.java'
    record = {
        'format': 1, 'checkedEpochNs': time.time_ns(),
        'initialIdentityFile': str(initial_file), 'initialIdentitySha256': sha(initial_file),
        'sourceMapFile': str(map_file), 'sourceMapSha256': sha(map_file),
        'moduleSourceCount': len(actual), 'missing': missing, 'added': added, 'changed': changed,
        'moduleSourcesUnchanged': not (missing or added or changed),
        'branch': git('branch', '--show-current'), 'head': git('rev-parse', 'HEAD'),
        'indexSha256': sha(index_path), 'materializerSha256': actual.get(materializer),
        'materializerTestSha256': actual.get(test),
        'productionSelection': 'Existing original dense pages and ownership implementation; no publication mask selected',
        'experimentalSourceDirectory': 'result-coordinate-evidence/publication-followup',
        'acceptedTimingComparison': False,
    }
    record['identityUnchanged'] = all(record[k] == initial[k] for k in (
        'branch', 'head', 'indexSha256', 'materializerSha256', 'materializerTestSha256', 'moduleSourceCount'))
    record['valid'] = record['moduleSourcesUnchanged'] and record['identityUnchanged']
    with output.open('x') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    print(json.dumps({'receipt': str(output), 'sha256': sha(output), 'valid': record['valid'],
                      'moduleSourceCount': len(actual), 'moduleSourcesUnchanged': record['moduleSourcesUnchanged'],
                      'identityUnchanged': record['identityUnchanged']}))
    assert record['valid'], 'Selected source or real Git identity changed; inspect preserved receipt'


if __name__ == '__main__':
    main()
